using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class WeakPV14Install {
 public const string Root="Assets/Shioka/調整Data/Fighter/Awari/Skill/5LP";static readonly int[] Holds={2,2,3,5,2,2,2,2,2,2};static readonly int[] Sole={1500,1502,1506,1501,1502,1501,1502,1503,1500,1500};
 public static void FinalizeLedger(){var asset=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(Root+"/Data.asset");var draft=UnityEngine.Object.Instantiate(asset);try{var holds=draft.data.spriteSequence.frames.Select(f=>f.holdFrames).ToArray();SkillSpriteFolderSync.Sync(asset,draft);if(!draft.data.spriteSequence.frames.Select(f=>f.holdFrames).SequenceEqual(holds))throw new Exception("Hold changed on resync");TrainingMoveDataEditor.SaveDraft(asset,draft);Debug.Log("WEAKP_V14 hold metadata finalized; active holds unchanged");}finally{UnityEngine.Object.DestroyImmediate(draft);}}
 public static void Run(){var asset=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(Root+"/Data.asset");if(asset.data.spriteSequence!=null&&asset.data.spriteSequence.frames.Length!=0)throw new Exception("Existing sequence must be inspected first");if(!AssetDatabase.IsValidFolder(Root+"/LegacySprite"))AssetDatabase.CreateFolder(Root,"LegacySprite");string error=AssetDatabase.MoveAsset(Root+"/Sprite/WeakP.png",Root+"/LegacySprite/WeakP.png");if(!string.IsNullOrEmpty(error))throw new Exception(error);var paths=Directory.GetFiles(Root+"/Sprite","*.png").OrderBy(x=>x,StringComparer.Ordinal).ToArray();if(paths.Length!=10)throw new Exception("Expected10 selected source PNGs");for(int i=0;i<paths.Length;i++){string path=paths[i].Replace((char)92,'/');var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.spritePixelsPerUnit=700;var settings=new TextureImporterSettings();importer.ReadTextureSettings(settings);settings.spriteAlignment=(int)SpriteAlignment.Custom;settings.spritePivot=new Vector2((.55f*1024-103)/1024,(1536-Sole[i])/1536f);settings.spriteMeshType=SpriteMeshType.FullRect;importer.SetTextureSettings(settings);importer.maxTextureSize=2048;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.alphaIsTransparency=true;importer.mipmapEnabled=false;importer.SaveAndReimport();}
 string before=JsonUtility.ToJson(asset.data);var draft=UnityEngine.Object.Instantiate(asset);try{SkillSpriteFolderSync.Sync(asset,draft);if(draft.data.spriteSequence.frames.Length!=10)throw new Exception("Folder sync count");for(int i=0;i<10;i++)draft.data.spriteSequence.frames[i].holdFrames=Holds[i];SkillSpriteFolderSync.Sync(asset,draft);if(!SkillSpriteFolderSync.ValidateSelection(asset,draft,out error))throw new Exception(error);var sequence=draft.data.spriteSequence;draft.data.spriteSequence=asset.data.spriteSequence;if(JsonUtility.ToJson(draft.data)!=before)throw new Exception("Nonvisual skill values changed");draft.data.spriteSequence=sequence;TrainingMoveDataEditor.SaveDraft(asset,draft);AssetDatabase.ImportAsset(Root+"/Data.asset",ImportAssetOptions.ForceUpdate);var loaded=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(Root+"/Data.asset");if(!loaded.data.spriteSequence.frames.Select(f=>f.holdFrames).SequenceEqual(Holds))throw new Exception("Saved holds mismatch");Debug.Log("WEAKP_V14 adopted10 sprites;24F provisional holds; source12 preserved;7.2/4.8/13.2 unchanged");}finally{UnityEngine.Object.DestroyImmediate(draft);}}
